function sxSoundex(word){
  var w=String(word).toUpperCase().replace(/[^A-Z]/g,'');
  if(!w) return { value:null, error:'需要至少一个英文字母' };
  var codes={ B:'1',F:'1',P:'1',V:'1', C:'2',G:'2',J:'2',K:'2',Q:'2',S:'2',X:'2',Z:'2',
    D:'3',T:'3', L:'4', M:'5',N:'5', R:'6' };
  var first=w[0], out=first, prev=codes[first]||'';
  for(var i=1;i<w.length;i++){
    var ch=w[i], c=codes[ch]||'';
    if(ch==='H'||ch==='W') continue; // H/W transparent: keep prev
    if(c && c!==prev) out+=c;
    prev=c;
  }
  out=(out+'000').slice(0,4);
  return { value:out, error:null };
}
function sxMetaphone(word){
  var w=String(word).toUpperCase().replace(/[^A-Z]/g,'');
  if(!w) return { value:null, error:'需要至少一个英文字母' };
  // simplified metaphone: transformations on common digraphs
  var s=w;
  s=s.replace(/^KN|^GN|^PN|^WR|^AE/,function(m){ return m.slice(1); });
  s=s.replace(/^X/,'S');
  s=s.replace(/MB$/,'M');
  s=s.replace(/PH/g,'F').replace(/TH/g,'0').replace(/SH/g,'X').replace(/CH/g,'X');
  s=s.replace(/CK/g,'K').replace(/SCH/g,'SK');
  s=s.replace(/C(?=[IEY])/g,'S').replace(/C/g,'K');
  s=s.replace(/G(?=[IEY])/g,'J').replace(/GH(?![AEIOU])/g,'').replace(/G/g,'K');
  s=s.replace(/D(?=G[IEY])/g,'J').replace(/D/g,'T');
  s=s.replace(/Z/g,'S').replace(/V/g,'F').replace(/Q/g,'K').replace(/W(?![AEIOU])/g,'').replace(/Y(?![AEIOU])/g,'');
  s=s.replace(/X/g,'KS');
  var first=s[0]||'';
  var rest=s.slice(1).replace(/[AEIOU]/g,'');
  s=first+rest;
  s=s.replace(/(.)\1+/g,'$1');
  return { value:s, error:null };
}
function sxGroup(words, algo){
  if(!Array.isArray(words)||!words.length) return { value:null, error:'单词列表为空' };
  var f=algo==='metaphone'?sxMetaphone:sxSoundex;
  var map={};
  for(var i=0;i<words.length;i++){
    var r=f(words[i]);
    if(r.error) return { value:null, error:'"'+words[i]+'": '+r.error };
    (map[r.value]=map[r.value]||[]).push(words[i]);
  }
  return { value:map, error:null };
}
function sxMatch(query, words, algo){
  var f=algo==='metaphone'?sxMetaphone:sxSoundex;
  var q=f(query);
  if(q.error) return { value:null, error:q.error };
  var out=[];
  for(var i=0;i<words.length;i++){
    var r=f(words[i]);
    if(!r.error && r.value===q.value) out.push(words[i]);
  }
  return { value:{ code:q.value, matches:out }, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { sxSoundex:sxSoundex, sxMetaphone:sxMetaphone, sxGroup:sxGroup, sxMatch:sxMatch };
}
if (typeof window !== 'undefined') {
  window.SoundexForgePure = { sxSoundex:sxSoundex, sxMetaphone:sxMetaphone, sxGroup:sxGroup, sxMatch:sxMatch };
}
